package scan

import (
	"fmt"
	"regexp"
	"sort"
	"strconv"
	"strings"
)

type poolDef struct {
	Pool
	Line     int
	Findings []Finding
}

var (
	poolHeaderRe = regexp.MustCompile(`^\[([A-Za-z0-9_.-]{1,64})\]$`)
	poolArrayRe  = regexp.MustCompile(`^(php_admin_value|php_admin_flag|php_value|php_flag|env)\[([A-Za-z0-9_.]{1,128})\]$`)
)

// poolKnown are scalar keys that map onto the model or are regenerated by
// Hostashi with its own defaults.
var poolKnown = map[string]bool{
	"user": true, "group": true, "listen": true, "listen.owner": true, "listen.group": true,
	"listen.mode": true, "listen.allowed_clients": true, "listen.backlog": true,
	"pm": true, "pm.max_children": true, "pm.start_servers": true, "pm.min_spare_servers": true,
	"pm.max_spare_servers": true, "pm.max_requests": true, "pm.process_idle_timeout": true,
	"pm.status_path": true, "ping.path": true, "request_terminate_timeout": true,
	"request_slowlog_timeout": true, "slowlog": true, "chdir": true, "catch_workers_output": true,
	"clear_env": true, "security.limit_extensions": true, "rlimit_files": true, "rlimit_core": true,
	"decorate_workers_output": true, "access.log": true, "access.format": true,
}

// phpSettingKnown are ini names Hostashi can carry as per-site PHP settings.
var phpSettingKnown = map[string]bool{
	"memory_limit": true, "upload_max_filesize": true, "post_max_size": true,
	"max_execution_time": true, "max_input_time": true, "max_input_vars": true,
	"date.timezone": true, "display_errors": true, "log_errors": true, "error_log": true,
	"error_reporting": true, "open_basedir": true, "disable_functions": true,
	"sys_temp_dir": true, "upload_tmp_dir": true, "session.save_path": true,
	"short_open_tag": true, "opcache.enable": true, "opcache.memory_consumption": true,
	"output_buffering": true, "allow_url_fopen": true, "expose_php": true,
}

// parsePools parses one php-fpm pool file. Values of env[...] are discarded
// right here so they cannot end up in a report.
func parsePools(src, source, version string) ([]poolDef, []Finding) {
	var out []poolDef
	var global []Finding
	var cur *poolDef
	skipGlobal := false
	for i, raw := range strings.Split(src, "\n") {
		ln := i + 1
		line := strings.TrimSpace(raw)
		if line == "" || strings.HasPrefix(line, ";") || strings.HasPrefix(line, "#") {
			continue
		}
		if line == "[global]" {
			// FPM global section inside pool.d: daemon settings, not a pool.
			cur = nil
			global = append(global, Finding{SevInfo, "pool_global_section", "[global] section in a pool file, ignored", source, ln})
			skipGlobal = true
			continue
		}
		if m := poolHeaderRe.FindStringSubmatch(line); m != nil {
			skipGlobal = false
			out = append(out, poolDef{Pool: Pool{Name: m[1], Version: version, Source: source, Settings: map[string]string{}}, Line: ln})
			cur = &out[len(out)-1]
			continue
		}
		if strings.HasPrefix(line, "[") {
			global = append(global, Finding{SevReview, "pool_bad_section", "unsupported section header", source, ln})
			cur = nil
			continue
		}
		k, v, ok := strings.Cut(line, "=")
		if !ok {
			global = append(global, Finding{SevReview, "pool_syntax", "line without '='", source, ln})
			continue
		}
		k, v = strings.TrimSpace(k), strings.Trim(strings.TrimSpace(v), `"`)
		if cur == nil {
			if skipGlobal {
				continue
			}
			if k != "include" { // [global] style keys outside a pool are not expected in pool.d
				global = append(global, Finding{SevReview, "pool_outside_section", fmt.Sprintf("key %q outside a pool section", k), source, ln})
			}
			continue
		}
		if m := poolArrayRe.FindStringSubmatch(k); m != nil {
			switch {
			case m[1] == "env":
				cur.EnvKeys = append(cur.EnvKeys, m[2]) // name only
			case phpSettingKnown[m[2]]:
				cur.Settings[m[1]+"["+m[2]+"]"] = v
			default:
				cur.Findings = append(cur.Findings, Finding{SevReview, "pool_unknown_setting", fmt.Sprintf("PHP setting %s[%s] is not modelled", m[1], m[2]), source, ln})
			}
			continue
		}
		switch k {
		case "user":
			cur.User = v
		case "group":
			cur.Group = v
		case "listen":
			cur.Listen = v
		case "pm":
			cur.PM = v
		case "pm.max_children":
			n, err := strconv.Atoi(v)
			if err != nil || n <= 0 {
				cur.Findings = append(cur.Findings, Finding{SevReview, "pool_bad_value", "pm.max_children is not a positive number", source, ln})
			}
			cur.MaxChldren = n
		default:
			if !poolKnown[k] {
				cur.Findings = append(cur.Findings, Finding{SevReview, "pool_unknown_key", fmt.Sprintf("pool key %q is not modelled", k), source, ln})
			}
		}
	}
	for i := range out {
		p := &out[i]
		sort.Strings(p.EnvKeys)
		if len(p.EnvKeys) > 0 {
			p.Findings = append(p.Findings, Finding{SevReview, "pool_env", fmt.Sprintf("pool sets %d environment variable(s) (%s); values not read into the report, may hold secrets", len(p.EnvKeys), strings.Join(p.EnvKeys, ", ")), source, p.Line})
		}
		if p.User == "" || p.Listen == "" {
			p.Findings = append(p.Findings, Finding{SevBlocker, "pool_incomplete", "pool has no user or no listen", source, p.Line})
		}
	}
	return out, global
}

// listenKey normalises an FPM listen value and an nginx fastcgi_pass value to
// the same form so the two can be matched: "unix:/path" or "tcp:host:port".
func listenKey(s string, fromNginx bool) string {
	if fromNginx {
		if strings.HasPrefix(s, "unix:") {
			return s
		}
	} else if strings.HasPrefix(s, "/") {
		return "unix:" + s
	}
	host, port, ok := strings.Cut(s, ":")
	if !ok { // FPM "9000" means all interfaces
		host, port = "*", s
	}
	if host == "localhost" || host == "127.0.0.1" || host == "*" || host == "0.0.0.0" {
		host = "127.0.0.1"
	}
	return "tcp:" + host + ":" + port
}
